-- PREPARATION ONLY: NOT AUTHORIZED FOR PRODUCTION EXECUTION.
-- Exact245new-only owner-maintenance data job;not the denied app-user RPC.
-- No auth claims,grants,RLS,new permanent RPC/table,profile/tutorial/Storage/progress writes.
-- Sources and all metadata fixed;on failure rollback catalog/history,sequence gaps remain.
begin;
set local lock_timeout='5s';
set local statement_timeout='90s';
select pg_catalog.pg_advisory_xact_lock(72483160);
lock table public.problem_catalog in share row exclusive mode;
do $guard$begin
 if not pg_has_role(current_user,(select relowner from pg_class where oid='public.problem_catalog'::regclass),'USAGE')then raise exception 'Owner-maintenance authority required';end if;
 if exists(select 1 from pg_trigger where tgrelid in('public.problem_catalog'::regclass,'public.problem_changes'::regclass)and not tgisinternal)then raise exception 'Unreviewed catalog/history trigger';end if;
 if auth.uid()is not null then raise exception 'Owner job requires unimpersonated database context';end if;
 if md5(replace(pg_get_functiondef('public.is_admin()'::regprocedure),E'\r\n',E'\n'))<>'5e9198d378eb116e17553d1b2b861b26'then raise exception 'Function baseline drift:is_admin';end if;
 if md5(replace(pg_get_functiondef('public.admin_save_problem(jsonb,bigint,integer)'::regprocedure),E'\r\n',E'\n'))<>'dacc200a2a3c0db0c9911c1cd16964ae'then raise exception 'Function baseline drift:admin_save_problem';end if;
 if md5(replace(pg_get_functiondef('public.validate_learning_problem(jsonb)'::regprocedure),E'\r\n',E'\n'))<>'670d939c72ef36a1bb9153d536415383'then raise exception 'Function baseline drift:validate_learning_problem';end if;
 if md5(replace(pg_get_functiondef('public.validate_priority_metadata(jsonb)'::regprocedure),E'\r\n',E'\n'))<>'b42556530c4bbdd6b0b91b5e401b3996'then raise exception 'Function baseline drift:validate_priority_metadata';end if;
 if(select count(*)from public.problem_catalog)<>748 or(select md5(jsonb_agg(jsonb_build_object('id',problem_id,'number',number,'body',body,'archived',archived,'revision',revision)order by problem_id collate "C")::text) h from public.problem_catalog)<>'4ddd1f24b8d4a3b3397961d8f159fe11'then raise exception 'Baseline catalog drift';end if;
 if(select md5(jsonb_agg(name order by name collate "C")::text)from public.problem_sources)<>'1862e713aa7ffe38862fbf79eb4fd584'then raise exception 'Source registry drift';end if;
 if(select last_value from public.problem_number_seq)<>748 or(select is_called from public.problem_number_seq)is distinct from true then raise exception 'Sequence drift: re-review;never reset/reuse';end if;
end$guard$;
create temp table p4_owner_inputs(ord integer primary key,body jsonb not null)on commit preserve rows;
create temp table p4_owner_before on commit preserve rows as select problem_id,to_jsonb(p)row from public.problem_catalog p;
create temp table p4_owner_receipts(ord integer primary key,problem_id text,number bigint,body jsonb)on commit preserve rows;
